) VALUES (
    'predazzo-venue-guide',
    '{"en": "Predazzo: Italy''s Nordic Jumping Center", "de": "Predazzo: Italiens Nordisches Sprungzentrum", "fr": "Predazzo : Le centre de saut nordique italien", "it": "Predazzo: Il centro italiano del salto nordico", "es": "Predazzo: El centro de saltos nórdicos de Italia", "pt": "Predazzo: O centro de saltos nórdicos da Itália", "nl": "Predazzo: Italië''s Noordse springcentrum", "ar": "بريداتسو: مركز القفز الشمالي الإيطالي", "ja": "プレダッツォ：イタリアのノルディックジャンプセンター", "zh": "Predazzo: Yidali de Beiou Tiaoyue Zhongxin", "ko": "프레다초: 이탈리아의 노르딕 점프 센터"}'::jsonb,
    '{"en": "Located in the Val di Fiemme, Predazzo offers world-class ski jumping facilities in a stunning Dolomite setting. Home to major Nordic events.", "de": "Im Val di Fiemme gelegen, bietet Predazzo erstklassige Skisprung-Anlagen in einer atemberaubenden Dolomiten-Kulisse.", "fr": "Situé dans le Val di Fiemme, Predazzo offre des installations de saut à ski de classe mondiale dans un cadre dolomitique spectaculaire.", "it": "Situato nella Val di Fiemme, Predazzo offre strutture di salto con gli sci di classe mondiale in uno scenario dolomitico mozzafiato.", "es": "Ubicado en el Val di Fiemme, Predazzo ofrece instalaciones de salto de esquí de clase mundial en un impresionante entorno de Dolomitas.", "pt": "Localizado no Val di Fiemme, Predazzo oferece instalações de salto de esqui de classe mundial em um cenário deslumbrante das Dolomitas.", "nl": "Gelegen in het Val di Fiemme, biedt Predazzo wereldklasse schansspringfaciliteiten in een prachtige Dolomieten setting.", "ar": "يقع في وادي فييمي، يقدم بريداتسو مرافق قفز تزلج عالمية المستوى في إطار دولوميتي مذهل", "ja": "ヴァル・ディ・フィエンメに位置するプレダッツォは、素晴らしいドロミテの環境で世界クラスのスキージャンプ施設を提供しています。", "zh": "Weiyue Val di Fiemme, Predazzo zai lingren jingtan de Duoluomite huanjing zhong tigong shijie ji huaxue tiaoyue sheshi.", "ko": "발 디 피에메에 위치한 프레다초는 멋진 돌로미테 환경에서 세계적 수준의 스키점프 시설을 제공합니다."}'::jsonb,
    '{"en": "<p>Predazzo serves as Italy''s premier <a href=\"/ski-jumping-guide/\">ski jumping</a> and <a href=\"/nordic-combined-guide/\">Nordic combined</a> venue. Located in the Trentino region''s Val di Fiemme, this facility has hosted world championships and continues to welcome international competition.</p><h2>The Jumping Hills</h2><p>The Trampolino Giuseppe Dal Ben complex features multiple hills suitable for training and competition at various levels. The main large hill provides the dramatic spectacle that ski jumping fans love, while smaller hills allow for development and practice.</p><p>The facility has been upgraded over the years to meet FIS standards for international competition, ensuring athletes have access to modern starting gates, in-run tracks, and landing areas.</p><h2>Nordic Combined</h2><p>For Nordic combined events, Predazzo offers both jumping and cross-country capabilities. Athletes like <a href=\"/johannes-lamparter-profile/\">Johannes Lamparter</a> and <a href=\"/jarl-magnus-riiber-profile/\">Jarl Magnus Riiber</a> have competed in this valley.</p><p>The cross-country trails wind through the beautiful Val di Fiemme landscape, providing challenging terrain for the skiing portion of combined events.</p><h2>Val di Fiemme</h2><p>The broader Val di Fiemme region is a Nordic sports paradise. The valley has hosted numerous world championships and continues to develop its winter sports infrastructure.</p><h2>Location and Access</h2><p>Predazzo is accessible from Innsbruck Airport (Austria) or Venice/Verona airports in Italy. The drive through the Dolomites is spectacular, though winter conditions require appropriate preparation.</p><h2>Spectator Experience</h2><p>The jumping venue offers good sightlines for spectators. The drama of watching athletes launch from the hill against the Dolomite backdrop creates memorable moments for fans.</p><h2>Local Culture</h2><p>The Trentino region offers a blend of Italian and Alpine culture. Visitors can enjoy local cuisine, traditional mountain hospitality, and the stunning natural beauty that makes this area special.</p>", "de": "<p>Predazzo dient als Italiens führende Wettkampfstätte für <a href=\"/ski-jumping-guide/\">Skisprung</a> und <a href=\"/nordic-combined-guide/\">Nordische Kombination</a>. Im Val di Fiemme in Trentino gelegen, hat diese Anlage Weltmeisterschaften ausgerichtet.</p><h2>Die Schanzen</h2><p>Der Trampolino Giuseppe Dal Ben Komplex verfügt über mehrere Schanzen für Training und Wettkampf auf verschiedenen Ebenen.</p><h2>Nordische Kombination</h2><p>Athleten wie <a href=\"/johannes-lamparter-profile/\">Johannes Lamparter</a> und <a href=\"/jarl-magnus-riiber-profile/\">Jarl Magnus Riiber</a> sind in diesem Tal angetreten.</p><h2>Val di Fiemme</h2><p>Die größere Region Val di Fiemme ist ein Paradies für den nordischen Sport.</p>", "fr": "<p>Predazzo sert de principale destination italienne pour le <a href=\"/ski-jumping-guide/\">saut à ski</a> et le <a href=\"/nordic-combined-guide/\">combiné nordique</a>. Situé dans le Val di Fiemme au Trentin, ce site a accueilli des championnats du monde.</p><h2>Les tremplins</h2><p>Le complexe Trampolino Giuseppe Dal Ben comprend plusieurs tremplins pour l''entraînement et la compétition.</p><h2>Combiné nordique</h2><p>Des athlètes comme <a href=\"/johannes-lamparter-profile/\">Johannes Lamparter</a> ont concouru dans cette vallée.</p>", "it": "<p>Predazzo serve come principale sede italiana per il <a href=\"/ski-jumping-guide/\">salto con gli sci</a> e la <a href=\"/nordic-combined-guide/\">combinata nordica</a>. Situato nella Val di Fiemme in Trentino, questa struttura ha ospitato campionati mondiali.</p><h2>I trampolini</h2><p>Il complesso Trampolino Giuseppe Dal Ben dispone di diversi trampolini per allenamento e competizione a vari livelli.</p><h2>Combinata nordica</h2><p>Atleti come <a href=\"/johannes-lamparter-profile/\">Johannes Lamparter</a> hanno gareggiato in questa valle.</p>", "es": "<p>Predazzo sirve como el principal lugar de Italia para el <a href=\"/ski-jumping-guide/\">salto de esquí</a> y la <a href=\"/nordic-combined-guide/\">combinada nórdica</a>. Ubicado en el Val di Fiemme en Trentino, esta instalación ha albergado campeonatos mundiales.</p><h2>Los trampolines</h2><p>El complejo Trampolino Giuseppe Dal Ben cuenta con múltiples trampolines.</p>", "pt": "<p>Predazzo serve como o principal local da Itália para <a href=\"/ski-jumping-guide/\">salto de esqui</a> e <a href=\"/nordic-combined-guide/\">combinado nórdico</a>. Localizado no Val di Fiemme em Trentino, esta instalação sediou campeonatos mundiais.</p><h2>As rampas</h2><p>O complexo Trampolino Giuseppe Dal Ben possui múltiplas rampas.</p>", "nl": "<p>Predazzo dient als Italië''s belangrijkste locatie voor <a href=\"/ski-jumping-guide/\">schansspringen</a> en <a href=\"/nordic-combined-guide/\">Noordse combinatie</a>. Gelegen in het Val di Fiemme in Trentino, heeft deze faciliteit wereldkampioenschappen georganiseerd.</p><h2>De schansen</h2><p>Het Trampolino Giuseppe Dal Ben complex beschikt over meerdere schansen.</p>", "ar": "<p>يعمل بريداتسو كمكان رئيسي في إيطاليا لـ<a href=\"/ski-jumping-guide/\">القفز على الجليد</a> و<a href=\"/nordic-combined-guide/\">الجمع الشمالي</a>. يقع في وادي فييمي في ترينتينو، وقد استضاف هذا المرفق بطولات العالم.</p><h2>منصات القفز</h2><p>يضم مجمع ترامبولينو جوزيبي دال بين عدة منصات قفز.</p>", "ja": "<p>プレダッツォは、イタリアの主要な<a href=\"/ski-jumping-guide/\">スキージャンプ</a>と<a href=\"/nordic-combined-guide/\">ノルディック複合</a>の会場として機能しています。トレンティーノ地方のヴァル・ディ・フィエンメに位置し、この施設は世界選手権を開催してきました。</p><h2>ジャンプ台</h2><p>トランポリーノ・ジュゼッペ・ダル・ベン複合施設には、様々なレベルでのトレーニングと競技に適した複数の台があります。</p>", "zh": "<p>Predazzo shi Yidali de zhuyao <a href=\"/ski-jumping-guide/\">huaxue tiaoyue</a> he <a href=\"/nordic-combined-guide/\">beiou fushi</a> changguan. Weiyue Teluntinuo diqu de Val di Fiemme, zhe ge sheshi yi juxing guoshijie jinbiaosai.</p><h2>Tiaotai</h2><p>Trampolino Giuseppe Dal Ben fuheti tigong duoge tiaotai.</p>", "ko": "<p>프레다초는 이탈리아의 주요 <a href=\"/ski-jumping-guide/\">스키점프</a>와 <a href=\"/nordic-combined-guide/\">노르딕 복합</a> 경기장으로 기능합니다. 트렌티노 지역의 발 디 피에메에 위치한 이 시설은 세계 선수권 대회를 개최해 왔습니다.</p><h2>점프대</h2><p>트람폴리노 주세페 달 벤 복합시설에는 여러 점프대가 있습니다.</p>"}'::jsonb,
    'venue-guide',
    'SJ',
    '{"en": "Predazzo venue guide - Italy''s ski jumping and Nordic combined center in the Val di Fiemme, featuring world-class jumping hills in Dolomite scenery.", "de": "Predazzo Venue Guide - Italiens Skisprung- und Nordische-Kombination-Zentrum im Val di Fiemme.", "fr": "Guide du site de Predazzo - Centre italien de saut à ski et de combiné nordique dans le Val di Fiemme.", "it": "Guida alla sede di Predazzo - Centro italiano di salto con gli sci e combinata nordica nella Val di Fiemme.", "es": "Guía del lugar de Predazzo - Centro italiano de salto de esquí y combinada nórdica en el Val di Fiemme.", "pt": "Guia do local de Predazzo - Centro italiano de salto de esqui e combinado nórdico no Val di Fiemme.", "nl": "Predazzo locatiegids - Italië''s schansspringen en Noordse combinatie centrum in het Val di Fiemme.", "ar": "دليل موقع بريداتسو - مركز القفز على الجليد والجمع الشمالي الإيطالي في وادي فييمي", "ja": "プレダッツォ会場ガイド - ヴァル・ディ・フィエンメにあるイタリアのスキージャンプとノルディック複合センター", "zh": "Predazzo changguan zhinan - Val di Fiemme de Yidali huaxue tiaoyue he beiou fushi zhongxin", "ko": "프레다초 경기장 가이드 - 발 디 피에메의 이탈리아 스키점프 및 노르딕 복합 센터"}'::jsonb,
    'published',
    NOW(),
    'evergreen'
) ON CONFLICT (slug) DO UPDATE SET
